export const Console = {
    log: (...args) => {
        if (typeof window != "undefined" && window.console)
            console.log(...args);
    },
    warn: (...args) => {
        if (typeof window != "undefined" && window.console)
            console.warn(...args);
    },
    error: (...args) => {
        if (typeof window != "undefined" && window.console)
            console.error(...args);
    },
};
